#!/bin/bash
# PreToolUse (Write|Edit): refuse edits that must never be made by hand.
#   - src/data/schema.rs is regenerated by `diesel migration run`.
#   - Migrations other than the newest one are already applied somewhere;
#     changing them silently diverges databases. Add a new migration instead.
# Creating a brand-new migration directory is always allowed.
set -euo pipefail

root="${CLAUDE_PROJECT_DIR:-$(pwd)}"
file=$(jq -r '.tool_input.file_path // empty')
[ -n "$file" ] || exit 0
case "$file" in /*) ;; *) file="$root/$file" ;; esac
rel="${file#"$root"/}"

deny() {
    jq -n --arg reason "$1" '{
        hookSpecificOutput: {
            hookEventName: "PreToolUse",
            permissionDecision: "deny",
            permissionDecisionReason: $reason
        }
    }'
    exit 0
}

if [ "$rel" = "src/data/schema.rs" ]; then
    deny "src/data/schema.rs is generated by diesel — never edit it by hand. Write a migration and run \`diesel migration run\`; it regenerates this file."
fi

case "$rel" in
    migrations/*/*)
        dir="${rel#migrations/}"
        dir="${dir%%/*}"
        latest=$(find "$root/migrations" -mindepth 1 -maxdepth 1 -type d -exec basename {} \; | sort | tail -n 1)
        if [ -d "$root/migrations/$dir" ] && [ "$dir" != "$latest" ]; then
            deny "migrations/$dir is not the newest migration ($latest) and is presumably applied already — do not rewrite it. Create a new migration with \`diesel migration generate <name>\` instead."
        fi
        ;;
esac

exit 0
